using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using Microsoft.Web.WebView2.Core;using Microsoft.Web.WebView2.Wpf;
namespace BrowserManager {
 public static class EmbeddedProbe {
  static readonly List<string> Rows=new List<string>();
  static void Check(bool value,string label){if(!value)throw new InvalidOperationException(label);Rows.Add("通过："+label);}
  static EmbeddedWindow Window(CoreWebView2Environment env,string id,string label,Action<string> notice=null,bool fixture=true){var w=new EmbeddedWindow(env,id,label,null,fixture,notice){ShowInTaskbar=false,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual,Left=-32000,Top=-32000};w.Show();return w;}
  static async Task Html(CoreWebView2 core,string html){var completion=new TaskCompletionSource<bool>();EventHandler<CoreWebView2NavigationCompletedEventArgs> handler=null;handler=delegate(object sender,CoreWebView2NavigationCompletedEventArgs args){core.NavigationCompleted-=handler;completion.TrySetResult(args.IsSuccess);};core.NavigationCompleted+=handler;core.NavigateToString(html);var completed=await Task.WhenAny(completion.Task,Task.Delay(15000));if(completed!=completion.Task||!await completion.Task)throw new TimeoutException();}
  static async Task Snapshot(EmbeddedWindow window,string path){window.UpdateLayout();var root=(FrameworkElement)window.Content;var browser=((DockPanel)root).Children.OfType<WebView2>().Single();using(var stream=new MemoryStream()){await window.Core.CapturePreviewAsync(CoreWebView2CapturePreviewImageFormat.Png,stream);stream.Position=0;var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=stream;bitmap.EndInit();bitmap.Freeze();int width=(int)Math.Ceiling(root.ActualWidth),height=(int)Math.Ceiling(root.ActualHeight);if(width<1||height<1)throw new InvalidOperationException();var chrome=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);chrome.Render(root);var visual=new DrawingVisual();using(var dc=visual.RenderOpen()){dc.DrawImage(chrome,new Rect(0,0,width,height));Point p=browser.TranslatePoint(new Point(0,0),root);dc.DrawImage(bitmap,new Rect(p.X,p.Y,browser.ActualWidth,browser.ActualHeight));}var rendered=new RenderTargetBitmap(width,height,96,96,PixelFormats.Pbgra32);rendered.Render(visual);var png=new PngBitmapEncoder();png.Frames.Add(BitmapFrame.Create(rendered));using(var output=File.Create(path))png.Save(output);}}
  public static int Run(string report,string png){int result=1;Rows.Clear();var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};string parent=Path.GetFullPath(Path.GetDirectoryName(report));Directory.CreateDirectory(parent);string root=Path.Combine(parent,"webview-fixture-"+Guid.NewGuid().ToString("N"));EmbeddedWindow a=null,b=null,reopened=null;CoreWebView2Environment env=null;var exited=new TaskCompletionSource<bool>();
   app.Startup+=async delegate{try{
    var options=EmbeddedPolicy.Options();env=await CoreWebView2Environment.CreateAsync(null,root,options);env.BrowserProcessExited+=delegate{exited.TrySetResult(true);};
    string idA=Guid.NewGuid().ToString("N"),idB=Guid.NewGuid().ToString("N");a=Window(env,idA,"测试账号 A（虚构）");await a.Initialize();b=Window(env,idB,"测试账号 B（虚构）");await b.Initialize();
    Check(a.Core.Profile.ProfileName==EmbeddedPolicy.Profile(idA)&&b.Core.Profile.ProfileName==EmbeddedPolicy.Profile(idB),"真实运行时按不同账号创建两个独立 profile");
    Check(!options.AllowSingleSignOnUsingOSPrimaryAccount,"真实环境明确关闭 Windows 账号单点登录");
    var cookie=a.Core.CookieManager.CreateCookie("fixture_session","FAKE_A","example.invalid","/");cookie.Expires=DateTime.UtcNow.AddHours(1);a.Core.CookieManager.AddOrUpdateCookie(cookie);
    var aCookies=await a.Core.CookieManager.GetCookiesAsync("https://example.invalid/");var bCookies=await b.Core.CookieManager.GetCookiesAsync("https://example.invalid/");Check(aCookies.Any(c=>c.Name=="fixture_session"&&c.Value=="FAKE_A")&&!bCookies.Any(c=>c.Name=="fixture_session"),"A 的虚构登录 cookie 不会出现在 B");
    var bc=b.Core.CookieManager.CreateCookie("fixture_session","FAKE_B","example.invalid","/");bc.Expires=DateTime.UtcNow.AddHours(1);b.Core.CookieManager.AddOrUpdateCookie(bc);aCookies=await a.Core.CookieManager.GetCookiesAsync("https://example.invalid/");bCookies=await b.Core.CookieManager.GetCookiesAsync("https://example.invalid/");Check(aCookies.Single(c=>c.Name=="fixture_session").Value=="FAKE_A"&&bCookies.Single(c=>c.Name=="fixture_session").Value=="FAKE_B","A/B 同名虚构 cookie 各自独立");
    string closeNotice=null;a.Close();reopened=Window(env,idA,"测试账号 A（虚构）",message=>closeNotice=message);await reopened.Initialize();aCookies=await reopened.Core.CookieManager.GetCookiesAsync("https://example.invalid/");Check(aCookies.Any(c=>c.Name=="fixture_session"&&c.Value=="FAKE_A"),"关闭 A 窗口后重新打开，虚构登录资料仍保留");
    Check(!reopened.Core.Settings.IsPasswordAutosaveEnabled&&!reopened.Core.Settings.IsGeneralAutofillEnabled,"网页登录窗口不自动保存密码或填入其他账号资料");
    string html="<!doctype html><meta charset=utf-8><style>body{margin:0;background:#f6f8fc;font:16px 'Microsoft YaHei UI';color:#203250}.card{max-width:470px;margin:42px auto;padding:34px;background:white;border-radius:16px}h1{font-size:26px}.demo{color:#b06613;font-size:13px}input{box-sizing:border-box;width:100%;padding:14px;border:1px solid #cfd7e5;border-radius:6px;margin:8px 0 20px}button{width:100%;padding:14px;background:#3467db;color:white;border:0;border-radius:6px}p{line-height:1.8;font-size:14px}</style><div class=card><div class=demo>离线界面示例 · 不是网易真实登录页</div><h1>账号 A 的内置登录窗口</h1><p>实际使用时，这里显示网易或战网的官方页面。</p><label>手机号 / 邮箱</label><input disabled placeholder='由你在官方页面填写'><label>密码 / 将军令验证</label><input disabled placeholder='首次登录由你手动完成'><button disabled>官方登录页面会显示在这里</button><p>每个账号资料独立保存，关闭窗口后可以继续使用。</p></div>";
    await Html(reopened.Core,html);
    await reopened.Core.ExecuteScriptAsync("window.open('about:blank','fixture_popup');");
    for(int i=0;i<50&&(reopened.LatestPopup==null||!reopened.LatestPopup.IsReady);i++)await Task.Delay(100);
    var popup=reopened.LatestPopup;if(popup==null||!popup.IsReady)throw new TimeoutException();var popupCookies=await popup.Core.CookieManager.GetCookiesAsync("https://example.invalid/");Check(popup.Core.Profile.ProfileName==reopened.Core.Profile.ProfileName&&popupCookies.Any(c=>c.Name=="fixture_session"&&c.Value=="FAKE_A"),"真实弹出验证窗口沿用同一账号资料");
    string opener="false";for(int i=0;i<20&&opener!="true";i++){opener=await popup.Core.ExecuteScriptAsync("Boolean(window.opener)");if(opener!="true")await Task.Delay(100);}Check(opener=="true","弹出窗口保留浏览器 opener 关系，未复制请求另开浏览器");
    try{await popup.Core.ExecuteScriptAsync("window.close()");}catch{if(!popup.ClosedAlready)throw;}for(int i=0;i<50&&!popup.ClosedAlready;i++)await Task.Delay(100);
    Check(popup.ClosedAlready,"网页 window.close 请求正常关闭验证窗口");Check(reopened.IsReady&&b.IsReady,"关闭验证页保留其他账号与原窗口");Check(!string.IsNullOrEmpty(closeNotice),"网页关闭后向管家返回状态提示");
    var blocked=Window(env,Guid.NewGuid().ToString("N"),"拦截提示测试",null,false);try{await blocked.Initialize();var completed=new TaskCompletionSource<bool>();blocked.Core.NavigationCompleted+=delegate(object sender,CoreWebView2NavigationCompletedEventArgs e){completed.TrySetResult(e.IsSuccess);};blocked.Core.Navigate("https://denied.example.invalid/next?secret=FAKE_NEVER_DISPLAY");var done=await Task.WhenAny(completed.Task,Task.Delay(1500));Rows.Add("虚构拦截诊断：完成事件="+(done==completed.Task)+"；提示="+blocked.DiagnosticStatus);Check(blocked.DiagnosticStatus.Contains("denied.example.invalid")&&!blocked.DiagnosticStatus.Contains("FAKE_NEVER_DISPLAY")&&(done!=completed.Task||!completed.Task.Result),"取消导航保留具体域名提示，临时参数不显示");}finally{if(!blocked.ClosedAlready)blocked.Close();}
    await Snapshot(reopened,png);Check(File.Exists(png),"内置网页与窗口外观已使用离线虚构内容截图");
    Rows.Add("运行时版本="+env.BrowserVersionString);Rows.Add("合计 "+Rows.Count(x=>x.StartsWith("通过："))+" 项真实运行时检查通过；全部数据为虚构，未连接真实登录网站、未读取真实账号或密码。");result=0;
   }catch(Exception error){Rows.Add("运行时检查停止："+error.GetType().Name);result=1;}{
    foreach(var w in new[]{a,b,reopened})if(w!=null&&!w.ClosedAlready)w.Close();if(env!=null)await Task.WhenAny(exited.Task,Task.Delay(10000));
    if(Path.GetFullPath(root).StartsWith(parent.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase)&&Path.GetFileName(root).StartsWith("webview-fixture-",StringComparison.Ordinal)){try{if(Directory.Exists(root))Directory.Delete(root,true);}catch{Rows.Add("虚构测试目录暂由运行时占用，保留在检查目录中，未强制结束进程。");}}
    File.WriteAllLines(report,Rows,new UTF8Encoding(true));app.Shutdown(result);
   }};app.Run();return result;
  }
 }
}
